using System;
using System.IO;
using System.Linq;
using CodeBrix.Graphics3D.Cycles.GltfRender;
using CodeBrix.Graphics3D.Cycles.Rendering;
using CodeBrix.Graphics3D.Gltf2.Schema2;
using SilverAssertions;
using Xunit;

namespace CodeBrix.Graphics3D.Cycles.Tests;

// The glTF example client (tools/gltf/CycleGltfRender) converting a procedural glTF model
// (generated by SampleModel, no external asset) on the CPU reference backend.
public class GltfSceneConverterTests
{
    private static readonly RenderSettings Small = new(32, 24, 8);

    private static ModelRoot LoadSample(bool withSun)
    {
        string path = Path.Combine(Path.GetTempPath(), "cycles-gltf-" + Guid.NewGuid().ToString("N") + ".glb");
        try
        {
            SampleModel.Create(withSun).SaveGLB(path);
            return ModelRoot.Load(path);
        }
        finally
        {
            File.Delete(path);
        }
    }

    [Fact]
    public void convert_maps_the_sample_glb_and_renders_it_on_the_cpu_reference()
    {
        //Arrange
        using CyclesScene scene = TestScenes.CreateCpuScene();
        ModelRoot model = LoadSample(withSun: false);

        //Act
        GltfConversionResult result = GltfSceneConverter.Convert(model, scene, new GltfConversionOptions { Width = Small.Width, Height = Small.Height });
        FilmBuffer film = scene.Render(Small);

        //Assert
        result.Meshes.Should().Be(3);
        result.MeshObjects.Should().Be(4);
        result.Triangles.Should().Be(16);
        result.Materials.Should().Be(4);
        result.Lights.Should().Be(1);
        result.DefaultLightAdded.Should().BeTrue();
        result.DefaultCameraUsed.Should().BeFalse();
        result.Warnings.Should().BeEmpty();
        film.Span.ToArray().All(float.IsFinite).Should().BeTrue();
        // Geometry is visible: not every pixel is the plain background colour.
        film.Span.ToArray().Where((value, index) => index % 4 == 0).Distinct().Count().Should().BeGreaterThan(20);
    }

    [Fact]
    public void convert_repeats_bit_for_bit_on_the_cpu_reference()
    {
        //Arrange
        ModelRoot model = LoadSample(withSun: true);
        using CyclesScene first = TestScenes.CreateCpuScene();
        using CyclesScene second = TestScenes.CreateCpuScene();
        GltfSceneConverter.Convert(model, first);
        GltfSceneConverter.Convert(model, second);

        //Act
        FilmBuffer a = first.Render(Small);
        FilmBuffer b = second.Render(Small);

        //Assert
        FilmComparison.Compare(a.Span, b.Span).BitwiseEqual.Should().BeTrue();
    }

    [Fact]
    public void convert_uses_the_files_directional_light_instead_of_the_default_sun()
    {
        //Arrange
        using CyclesScene scene = TestScenes.CreateCpuScene();
        ModelRoot model = LoadSample(withSun: true);

        //Act
        GltfConversionResult result = GltfSceneConverter.Convert(model, scene);

        //Assert
        result.Lights.Should().Be(1);
        result.DefaultLightAdded.Should().BeFalse();
    }

    [Fact]
    public void convert_frames_the_scene_bounds_with_a_default_camera_when_asked()
    {
        //Arrange
        using CyclesScene scene = TestScenes.CreateCpuScene();
        ModelRoot model = LoadSample(withSun: false);

        //Act
        GltfConversionResult result = GltfSceneConverter.Convert(model, scene, new GltfConversionOptions { ForceDefaultCamera = true });
        FilmBuffer film = scene.Render(Small);

        //Assert
        result.DefaultCameraUsed.Should().BeTrue();
        result.BoundsMinimum.X.Should().BeApproximately(-3f, 1e-5f);
        result.BoundsMaximum.Z.Should().BeApproximately(3f, 1e-5f);
        result.BoundsMaximum.Y.Should().BeApproximately(1.2f, 1e-5f);
        film.Span.ToArray().All(float.IsFinite).Should().BeTrue();
    }

    [Fact]
    public void convert_rejects_a_model_without_triangles()
    {
        //Arrange
        using CyclesScene scene = TestScenes.CreateCpuScene();
        ModelRoot model = ModelRoot.CreateModel();
        model.UseScene("empty").CreateNode("nothing");

        //Act
        Action convert = () => GltfSceneConverter.Convert(model, scene);

        //Assert
        convert.Should().Throw<InvalidOperationException>();
    }

    [Fact]
    public void film_comparison_applies_the_practical_and_strict_criteria()
    {
        //Arrange
        float[] reference = [1f, 0f, .5f, 2f];
        float[] actual = [1f, 1e-6f, .5f + 1e-3f, 2f];

        //Act
        FilmComparison comparison = FilmComparison.Compare(actual, reference);

        //Assert
        comparison.StrictDifferences.Should().Be(2);
        comparison.PracticalFailures.Should().Be(1);
        comparison.BitwiseEqual.Should().BeFalse();
        comparison.MaximumAbsoluteError.Should().BeApproximately(1e-3, 1e-6);
        FilmComparison.Compare(reference, reference).BitwiseEqual.Should().BeTrue();
    }

    [Fact]
    public void film_file_writes_the_raw_floats_and_a_header()
    {
        //Arrange
        using CyclesScene scene = TestScenes.CreateCpuScene();
        GltfSceneConverter.Convert(LoadSample(withSun: false), scene);
        FilmBuffer film = scene.Render(Small);
        string path = Path.Combine(Path.GetTempPath(), "cycles-gltf-" + Guid.NewGuid().ToString("N") + ".bin");

        try
        {
            //Act
            string sha256 = FilmFile.Write(path, film, scene.Backend, Small.Samples, "sample.glb");

            //Assert
            File.ReadAllBytes(path).Length.Should().Be((int)Small.FloatCount * sizeof(float));
            File.ReadAllText(path + ".json").Should().Contain(sha256);
        }
        finally
        {
            File.Delete(path);
            File.Delete(path + ".json");
        }
    }

    [Fact]
    public void sample_model_has_a_perspective_camera_and_shared_cube_mesh()
    {
        //Arrange / Act
        ModelRoot model = SampleModel.Create();

        //Assert
        model.LogicalMeshes.Count.Should().Be(3);
        model.LogicalCameras.Single().Settings.IsPerspective.Should().BeTrue();
        model.DefaultScene.VisualChildren.Count(node => node.Mesh != null && node.Mesh.Name == "cube").Should().Be(2);
    }
}
